    token: process.env.VAULT_TOKEN,
  });

  const secrets = await client.read('secret/data/myapp/config');
  return secrets.data.data;
}

// Load secrets before starting app
loadSecrets()
  .then(secrets => {
    app.listen(3000);
  })
  .catch(err => {
    console.error('Failed to load secrets:', err);
    process.exit(1);
  });
```

