### 4. 🚨 No Authentication/Authorization (OWASP A01:2021 - Broken Access Control)

**Issue:** The `/users` endpoint exposes data without any authentication.

```javascript
// CURRENT: Completely open endpoint
app.get('/users', (req, res) => {
  res.json([...]); // Exposes all users to anyone
});
```

**Recommendation:** Implement authentication middleware:

```javascript
// Simple JWT authentication example
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protect sensitive endpoints
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([...]);
});
```

