### 6. 🚨 No CORS Configuration (OWASP A01:2021 - Broken Access Control)

**Issue:** No CORS policy, which could allow unauthorized cross-origin requests.

```javascript
// CURRENT: No CORS - defaults to allowing all (insecure)
```

**Recommendation:** Configure CORS properly:

```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests with no origin (mobile apps, curl, etc.)
    // In production, replace with specific allowed origins
    const allowedOrigins = ['https://yourdomain.com', 'https://app.yourdomain.com'];
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count'],
  credentials: true,
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));
```

